    balance = 0
    need = 0
    min_distance = float('inf')
    i = 0
    j = len(S) - 1

    while i < j - 1:
        if S[i] == '(':
            j -= 1
        else:
            i += 1

        balance += 1
        if balance == need:
            min_distance = min(min_distance, j - i)

    S.reverse()
    balance = 0
    need = 0
    i = 0
    j = len(S) - 1

    while i < j - 1:
        if S[i] == '(':
            j -= 1
        else:
            i += 1

        balance += 1
        if balance == need:
            min_distance = min(min_distance, j - i)

    return min_distance

def optimize_string_by_swap(S, idx):
    if idx >= len(S):
        return min_distance_to_balance(S)

    first_part = optimize_string_by_swap(S[:idx], 0)
    second_part = optimize_string_by_swap(S[idx+1:], 0)
    if idx < len(S) - 1:
        first_part += optimize_string_by_swap(S[idx+2:], len(S[idx:]))
    if idx:
        second_part += optimize_string_by_swap(S[:idx-1], 0)

    left = idx + first_part
    right = len(S) - 1 - second_part

    if (S[idx] == '(' and not second_part > remaining_open - 1) or (
        S[idx] == ')' and not (idx == 0 and first_part == len(S) - remaining_close - 1)):
        return 0

    min_swap = remaining_open + remaining_close + optimal_betweenswap(left, right)

    if first_part - 2 * (idx - 1) >= -remaining_close and remaining_close >= max(first_part, second_part):
        if first_part > second_part and (not S[idx] == '(' and optimal_betweenswap(left, second_part - 1) + 1 >= min_swap):
            min_swap = 1 + optimal_betweenswap(left, second_part - 1)

    if (idx - 1 > 0 and first_part + 1 - (len(S) - idx - 1) >= -remaining_close and second_part >= max(first_part, remaining_close)) or (
