    information = [0] * 26
    info = {}

    for i in range(len(s)):
        if i >= k:
            old = 1 if s[i - k] in info.keys() else 0
            info[s[i - k]] = old

        if i >= 2*k:
            code = 1001 + (ord(s[k-1]) - ord('a')) * 5 + \
                   (ord(s[i%26]) - ord('a')) * 100 + 0
            if code in information:
                prefix_length[i + 1] = information[code]
            for j in range(1, 26):
                if (j - 1) in information and (j + 1) in information:
                    prefix_length[i + 1] = max(prefix_length[i + 1], information[1002 - code] + j)
            information[1001 + (ord(s[i%26]) - ord('a')) * 5 + (ord(s[k-1]) - ord('a')) * 100 + (ord(s[i + k/2) % 26] - ord('a')) * 1000] = \
                max(prefix_length[i + 1], information[1001 - (ord(s[k-1]) - ord('a')) * 5 - (ord(s[i%26]) - ord('a')) * 100 - (ord(s[i + k/2) % 26] - ord('a')) * 1000] + (ord(s[i + k/2] - ord('a'))))
            for j in information:
                if j > 2600:
                    prefix_length[i + 1] = max(prefix_length[i + 1], -1)
                    break
            prefix_length[i + 1] = information[1001 + (ord(s[i%26]) - ord('a')) * 5 + (ord(s[k-1]) - ord('a')) * 100 + (ord(s[i + k/2] - ord('a')) - ord('a')) * 1000]
        for j in range(1, 26):
            if j in information:
                if s[i%26] == chr(ord('a') + j):
                    prefix_length[i + 1] = min(prefix_length[i + 1], information[1000 + (j - 1) * 100] + j)
                if s[i%26] == chr(ord('a') + 25 - j):
                    prefix_length[i + 1] = min(prefix_length[i + 1], information[1000 + (25 - j - 1) * 100] + 25 - j)
            else:
                prefix_length[i + 1] = min(prefix_length[i + 1], information[1000 + j * 100])
            if s[i%26] == 'a':
                prefix_length[i + 1] = min(prefix_length[i + 1], information[j%26 * 100])

    return prefix_length[len(s)]
