import itertools

def mod_inverse(a, m):
    """Calculate the modular inverse of a under modulo m."""
    return pow(a, -1, m)

def factorial_modulo(n, mod=998244353):
    """Calculate the factorial of n modulo the given modulus."""
    result = 1
    for i in range(1, n + 1):
        result = (result * i) % mod
    return result

def power_modulo(a, b, m):
    """Calculate (a^b) modulo m using modular exponentiation."""
    result = 1
    a = a % m
    while b:
        if b & 1:
            result = (result * a) % m
        b = b >> 1
        a = (a * a) % m
    return result

def count_good_sequences(n):
    if n == 1:
        return [1]
    factors = [2]
    s = set(factors)
    for i in range(2, n + 1):
        if i in s:
            continue
        j = 2
        while j * i <= n:
            s.add(j * i)
            factors.append(j * i)
            j += 1
    fact = 1
    for f in factors:
        fact = (fact * f) % 998244353
    result = fact
    for f in factors:
        tmp = factorial_modulo(len(factors) - 1, 998244353)
        result = (result * (-tmp) % 998244353) % 998244353
    result = int(result * power_modulo(mod_inverse(len(factors) - 1), 998244352, 998244353)) % 998244353
    return result

def calculate_sum(n):
    result = [0] * n
    for i in range(1, n + 1):
        result[i - 1] = count_good_sequences(i)
    return result

