def dfs(node, parent, edges, nodes_red, score):
    for neighbor in edges[node]:
        if neighbor == parent:
            continue
        score_red, score_blue, nodes_red = dfs(neighbor, node, edges, nodes_red, score)
        score += (nodes_red - min(nodes_red, score_blue)) * (node - min(node, score_red))
        nodes_red = min(nodes_red, score)
