import sys

def odd_proper_prefixes(s, n, k):
    if k == 1:
        return n

    def is_odd_prefix_prefix(s, target):
        l = len(target)
        if l % 2 == 0 or target[0] != s[l-1]:
            return False
        for i in range(l-1, 0, -1):
            if s[i-1] != s[-i]:
                return False
        return True

    max_prefixes = [0] * n
    low, high = 0, n - k

    while low < high:
        mid = (low + high + 1) // 2
        count = 0

        for i in range(0, n-k, k-1):
            if is_odd_prefix_prefix(s, i+k):
                count += 1

        if count > mid:
            low = mid

        else:
            high = mid - 1
            max_prefixes[low] = mid

    return max_prefixes

