def calculate_oop_prefix_max_length(n, s):
    MOD = 10**9 + 7
    prefix_sums = [0] * (n + 1)

    for i in range(1, n + 1):
        prefix_sums[i] = prefix_sums[i-1] + (1 if i % 2 else -1)

    @lru_cache(maxsize=None)
    def find_longest_sequence(index, pad):
        if index == n - pad + 1:
            return 1
        if index < 0:
            return -1
        length = 0
        seq = ''
        while len(seq) < pad and index >= 0:
            length += 1
            seq += s[index]
            index -= 1
        if len(seq) % 2 == 0:
            return 0
        return length

    for i in range(2, 2*n // 2 + 1):
        length = find_longest_sequence(n - i + 1, i // 2)
        if length == 1:
            prefix_sums[i] -= 1
    answer = [0] * n
    for i in range(n):
        length = 2 * i % (2 * n - 4 * int((i + 1) * (i + 2) / 2)) + 1
        if length <= n // 2:
            answer[i] = prefix_sums[length + 1]
        else:
            answer[i] = -1
    return answer


