from collections import defaultdict
from math import pow
from sys import stdin

def fast_mod(exp, m, mod):
    return pow(exp, m, mod)

class Graph:
    def __init__(self, nodes):
        self.edges = defaultdict(set)
        self.nodes = nodes

    def get_edges(self, from_node):
        return self.edges[from_node]

    def add_edge(self, from_node, to_node, cost):
        self.edges[from_node].add((to_node, cost))
        self.edges[to_node].add((from_node, cost))

def compute_cost(graph, nodes, paths):
    leaf_to_root = defaultdict(int)
    depth = defaultdict(int)
    cost = {}

    # Initialize leaf_to_root
    for node in nodes:
        leaf_to_root[node] = False

    # Compute costs
    visited = set()
    for path in paths:
        for params in path:
            root = graph.nodes[0]
            from_node, to_node, cost = params
            leaf_to_root[to_node] |= leaf_to_root[from_node]
            graph.add_edge(from_node, to_node, abs(cost))
            if to_node not in visited:
                visited.add(to_node)
                depth[to_node] = depth[from_node] + 1
                cost[to_node] = cost[from_node] + cost[from_node]

            from_node = to_node

    # Find the leaf that points to root
    for leaf in leaf_to_root:
        if leaf_to_root[leaf]:
            root = leaf

    # Scan the graph and collect leaf to root paths
    stack = [root]
    path = [root]
    count = list(leaf_to_root.values()).count(True)
    assigned = {root: count // 2}
    used_edges = 0

    while len(stack) > 0:
        from_node = stack[-1]
        for (to_node, _) in graph.get_edges(from_node):
            if leaf_to_root[to_node]:
                leaf_to_root[to_node] = False
                for leaf in leaf_to_root:
                    if leaf not in assigned and leaf not in used_edges:
                        path.append(leaf)
                        used_edges.add(leaf)
                        count -= 1
                        assigned[path[-1]] = count // 2
                        depth[path[-1]] = depth[from_node] + 1
                        path[-2].add(path[1], depth[path[1]])
                        if assigned[path[-1]] == 0:
                            used_edges.discard(path[-1])
                used_edges.add(to_node)
                path = [from_node, to_node]

        removed_entry = path.pop()
        assigned[removed_entry] = 0
        depth[removed_entry] = 0
        stack.pop()

    return cost, len(used_edges)

def main():
    lines = list(map(int, stdin.read().split()))
    N = lines.pop(0)
    M = lines.pop(0)
    nodes = [i for i in range(N)]

    repairgraph, paths = [nodes], []

    # UnorderedLines = {list(formatted partition of first line), list(formatted partition of second line)}
    for line_number in range(M):
        line = list(map(lambda x: int(x) - 1 if x != 0 else 0, lines.pop(0).split()))
        nodes_from, nodes_to, costs = line[0], line[1], line[2:]
        repairgraph = Graph(nodes)
        for i in range(len(costs) // 2):
            for j in range(len(costs) // 2):
                repairgraph.add_edge(costs[2 * i] | costs[2 * i + 1], costs[2 * j] | ((costs[2 * j + 1] and NOT_OF_COSTS) or (2 * j + 1 == i)), fast_mod(costs[2 * j] | ((costs[2 * j + 1] and NOT_OF_COSTS) or (2 * j + 1 == i)) | (NOT_OF_COSTS and fast_mod(costs[2 * i], 2)), 1000000007))
        paths = [task for task in [(cost[2 * i], costs[2 * i:j]) for i in range(len(costs) // 2) for j in range(2 * i + 2, 2 * i + 3)] if task]

    cost, edges = compute_cost(repairgraph, nodes, paths)

    print(cost, edges)

if __name__ == "__main__":
    main()
