from math import gcd

def count_tuples_with_gcd(numerator, denominator, lcd_denominator):
    lcm = (numerator * denominator + numerator - 1) // (numerator - 1) * (denominator // gcd(numerator, denominator))
    lcm_min_denominator = lcm / denominator
    lcm_min_num = lcm
    return lcm_min_denominator, lcm_min_num

def count_divisors(n):
    if n == 1:
        return 0
    divisors = 1
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            divisors += 2
            if i != n // i:
                divisors += 1
    return divisors

def solve():
    n = int(input().strip())
    constraints = []
    max_beautiful = 0
    for i in range(n):
        a, b, p = [int(x) for x in input().strip().split()]
        total, temp = count_tuples_with_gcd(a, b, p)
        max_beautiful = max(max_beautiful, total)
        weight = a * b
        constraints.append((b, weight, total, temp))

    max_beautiful_pairs = max_beautiful + max(1, max_beautiful - 1)
    pairs_possible = 1 << (n + 1)
    not_valid = 0
    for i in range(1, pairs_possible, 2):
        valid = True
        for j in range(n):
            if i & (1 << j + 1) == 0:
                it = constraints[j]
                if not valid:
                    break
                if (it[0] + 1) % (1 << (j + 1)):
                    valid = False
                    not_valid += 1
                    break
        else:
            max_beautiful_pairs -= pairs_possible - i
    return max_beautiful_pairs + max_beautiful_not_valid(constraints)

def max_beautiful_not_valid(constraints):
    created = 0
    for i in range(1, powersum(len(constraints)[0] + 1) + 1):
        sum_constraint = 1
        for j in range(len(constraints)):
            num = powersum(constraints[j][0])
            if i & (1 << j + 1):
                sum_constraint -= pow(constraints[j][1], num)
            else:
                sum_constraint += pow(constraints[j][1], num)
        created += sum_constraint
    return created

def powersum(n):
    counter = 1
    result = 0
    while counter <= n:
        if n % counter == 0:
            result += 1
        counter += 1
    return result

print(solve())
