from typing import List

def min_cost_to_reach_N(N: int, A: List[int]) -> int:
    pre = [0] * (N + 1)
    pre[1] = A[0]
    for i in range(2, N + 1):
        for j in range(1, i + 1):
            a1, a2, a = A[i - 1], pre[j - 1], pre[i - 1]
            if j <= a1 <= min(j + a, N):
                pre[i] = max(pre[i], a)
            else:
                pre[i] = a
    return pre[N]

