import math

def max_sweet_tooth(n, l, r, k):
    if (n - 1) * 2 * (k - 1) < 2 * l + 2 * r:
        return -1
    difference = (n - 1) * 2 * (k - 1) - 2 * l - 2 * r
    if difference % (n - 1) == 0:
        return math.ceil(difference / (n - 1))
    else:
        return math.ceil(difference / (n - 1)) + 1

