def cyclic_shift(sequence):
    last_char = sequence[-1]
    for i in range(len(sequence)):
        sequence = sequence[i:] + sequence[:i]
        if sequence != sequence[1::] + sequence[0]:
            return sequence[0] + sequence  # Return the first character followed by the concatenated sequence
    return sequence

def find_min_sequence(sequence):
    if sequence == "()":
        return "()"

    minimized_sequence = sequence
    for _ in range(len(sequence)):
        minimized_sequence = cyclic_shift(minimized_sequence)
        if minimized_sequence == "()" or minimized_sequence == "()()":
            break
    return cyclic_shift(minimized_sequence)

